# Профиль, % жира и кольца Б/Ж/У в дневнике. Запуск: python3 tests/profile_bf_check.py index.html [папка_скриншотов]
import asyncio,json,os,sys,math,shutil,tempfile,http.server,threading,functools,struct,zlib
from playwright.async_api import async_playwright
HTML=os.path.abspath(sys.argv[1]);SHOT=sys.argv[2] if len(sys.argv)>2 else None
tmp=tempfile.mkdtemp();shutil.copy(HTML,tmp+'/index.html')
if os.path.isdir(os.path.dirname(HTML)+'/media'):os.symlink(os.path.dirname(HTML)+'/media',tmp+'/media')
srv=http.server.ThreadingHTTPServer(('127.0.0.1',0),functools.partial(type('Q',(http.server.SimpleHTTPRequestHandler,),{'log_message':lambda *a:None}),directory=tmp))
threading.Thread(target=srv.serve_forever,daemon=True).start();URL=f'http://127.0.0.1:{srv.server_address[1]}/index.html'
def png(w,h):
  raw=b''.join(b'\x00'+bytes([200,120,60]*w) for _ in range(h))
  ch=lambda t,d:struct.pack('>I',len(d))+t+d+struct.pack('>I',zlib.crc32(t+d)&0xffffffff)
  return b'\x89PNG\r\n\x1a\n'+ch(b'IHDR',struct.pack('>IIBBBBB',w,h,8,2,0,0,0))+ch(b'IDAT',zlib.compress(raw))+ch(b'IEND',b'')
open(tmp+'/face.png','wb').write(png(400,300))
R=[]
def ok(n,c,x=''):R.append(bool(c));print(('PASS ' if c else 'FAIL ')+n+(' · '+str(x) if x!='' else ''))
async def m():
  async with async_playwright() as p:
    b=await p.chromium.launch();ctx=await b.new_context(viewport={'width':390,'height':844},device_scale_factor=2,is_mobile=True,has_touch=True)
    pg=await ctx.new_page();errs=[];pg.on('pageerror',lambda e:errs.append(str(e)))
    await pg.goto(URL);await pg.wait_for_timeout(300)
    await pg.evaluate("localStorage.setItem('gym45_food_v1',JSON.stringify([{id:'a1',date:localDate(),name:'Яйца',kcal:453,p:41,f:30,c:4}]))");await pg.reload();await pg.wait_for_timeout(300)
    await pg.evaluate("el('login').style.display='none';renderFood();show('food')");await pg.wait_for_timeout(100)
    ok('дневник: три кольца Б/Ж/У с данными внутри',await pg.evaluate("['P','F','C'].every(k=>el('ring'+k))&&el('foodP').textContent==='41'&&el('foodF').textContent==='30'&&el('foodC').textContent==='4'"))
    ok('дневник: без нормы кольца пустые, полоса нормы скрыта',await pg.evaluate("el('ntVsNorm').hidden&&el('ringPn').textContent==='г'"))
    await pg.evaluate("ntTab('norm')");await pg.wait_for_timeout(80)
    ok('норма: переключателя «Оригинал Штурм 30» нет, слова «Штурм» на экране нет',await pg.evaluate("!el('ntMethod')&&!el('scr-food').innerText.includes('Штурм')"))
    await pg.evaluate("document.querySelector('#ntSex [data-v=\"male\"]').click();document.querySelector('#ntGoal [data-v=\"gain\"]').click()")
    await pg.fill('#ntAge','45');await pg.fill('#ntWeight','96');await pg.fill('#ntHeight','180');await pg.select_option('#ntAct','light')
    await pg.evaluate("el('ntCalc').click()");await pg.wait_for_timeout(120)
    x0=json.loads(await pg.evaluate("JSON.stringify(ntTarget(ntT()))"))
    ok('без % жира — прежний расчёт (2821 ккал, Б 157,5)',x0['kcal']==2821 and x0['p']==157.5,(x0['kcal'],x0['p']))
    ok('без % жира — нет отсылки к Штурм 30',await pg.evaluate("!el('ntNormOut').innerText.includes('Штурм')&&el('ntNormOut').innerText.includes('Укажи % жира')"))
    await pg.fill('#ntBf','20');await pg.evaluate("el('ntCalc').click()");await pg.wait_for_timeout(120)
    t=json.loads(await pg.evaluate("localStorage.getItem('gym45_nutrition_target_v1')"));x=json.loads(await pg.evaluate("JSON.stringify(ntTarget(ntT()))"))
    lbm=96*.8;bmr=370+21.6*lbm;kc=round(bmr*1.375*1.1)
    ok('% жира хранится в норме',t.get('bf')==20)
    ok('с % жира: Кэтч — МакАрдл от сухой массы 76,8 кг',x['resting']==round(bmr) and x['kcal']==kc,(x['resting'],x['kcal'],kc))
    ok('с % жира: белок 2,2 г/кг сухой массы, жиры ≥1 г/кг, углеводы — остаток',abs(x['p']-round(lbm*2.2,1))<.05 and x['f']>=lbm-.05 and abs(x['c']-round((kc-x['p']*4-x['f']*9)/4,1))<.06,(x['p'],x['f'],x['c']))
    ok('пояснение «Расчёт от сухой массы» на экране',await pg.evaluate("el('ntNormOut').innerText.includes('Расчёт от сухой массы')"))
    bad=await pg.evaluate("(()=>{el('ntBf').value='75';el('ntCalc').click();return el('ntErr').textContent})()")
    ok('% жира вне 3–60 — понятная ошибка, норма не перезаписана','от 3 до 60' in bad and json.loads(await pg.evaluate("localStorage.getItem('gym45_nutrition_target_v1')"))['bf']==20,bad)
    await pg.fill('#ntBf','20')
    # пример % жира
    await pg.evaluate("el('ntBfEx').click()");await pg.wait_for_timeout(100)
    ok('«Пример % жира»: 6 фигур для мужчин',await pg.evaluate("!el('bfSheet').hidden&&el('bfGrid').querySelectorAll('.bf-it svg').length===6"))
    if SHOT:await pg.screenshot(path=SHOT+'/bf-male.png')
    await pg.evaluate("document.querySelector('#bfSex [data-v=\"female\"]').click()");await pg.wait_for_timeout(60)
    ok('для женщин — своя шкала и поле «Бёдра»',await pg.evaluate("el('bfGrid').innerText.includes('20–22%')&&!el('bfHipL').hidden"))
    if SHOT:await pg.screenshot(path=SHOT+'/bf-female.png')
    await pg.evaluate("document.querySelector('#bfSex [data-v=\"male\"]').click()")
    ok('шкала без горизонтальной прокрутки',await pg.evaluate("el('bfSheet').querySelector('.sub-card').scrollWidth<=el('bfSheet').querySelector('.sub-card').clientWidth+1"))
    await pg.fill('#bfH','180');await pg.fill('#bfNeck','40');await pg.fill('#bfWaist','95');await pg.evaluate("el('bfCalc').click()")
    nv=495/(1.0324-.19077*math.log10(95-40)+.15456*math.log10(180))-450
    got=await pg.evaluate("el('bfOut').innerText")
    ok('лента (ВМС США): 180/40/95 → %.1f%%'%nv,('%.1f'%nv).replace('.',',') in got,got)
    await pg.evaluate("el('bfUse').click()");await pg.wait_for_timeout(60)
    ok('«Подставить» заполняет поле % жира и закрывает окно',await pg.evaluate("el('bfSheet').hidden")and abs(float(await pg.input_value('#ntBf'))-round(nv,1))<.01)
    await pg.evaluate("el('ntBfEx').click()");await pg.evaluate("el('bfGrid').querySelectorAll('.bf-it')[2].click()")
    ok('выбор фигуры подставляет её % (18–20% → 19)',await pg.input_value('#ntBf')=='19')
    await pg.evaluate("el('ntCalc').click()");await pg.wait_for_timeout(100)
    # кольца с нормой
    await pg.evaluate("ntTab('diary')");await pg.wait_for_timeout(60)
    r=await pg.evaluate("(()=>{const x=ntTarget(ntT());const d=el('ringP').querySelector('.rf').getAttribute('stroke-dasharray').split(' ').map(Number);return {x,d,n:el('ringPn').textContent,kv:el('ntVsNorm').innerText}})()")
    exp=41/r['x']['p']*2*math.pi*17
    ok('кольцо белка заполнено пропорционально съеденному',abs(r['d'][0]-exp)<.1 and r['n'].startswith('из '),(r['d'],round(exp,2),r['n']))
    ok('полоса калорий: норма и остаток','Норма на день' in r['kv'] and 'осталось' in r['kv'],r['kv'])
    ok('дневник без горизонтальной прокрутки',await pg.evaluate("document.documentElement.scrollWidth<=innerWidth+1"))
    if SHOT:await pg.screenshot(path=SHOT+'/diary-rings.png')
    # профиль
    await pg.evaluate("show('home')");await pg.evaluate("el('homeAvatar').click()");await pg.wait_for_timeout(100)
    ok('кнопка профиля на главном открывает «Профиль»',await pg.evaluate("currentScreen==='profile'"))
    ok('профиль подхватил данные из нормы',await pg.evaluate("[el('pfAge').value,el('pfW').value,el('pfH').value,el('pfBf').value].join('|')")=='45|96|180|19')
    await pg.set_input_files('#pfPhotoIn',tmp+'/face.png');await pg.wait_for_timeout(500)
    ok('фото: сохранено квадратом 320 px и показано на главном',await pg.evaluate("(()=>{const p=JSON.parse(localStorage.getItem('gym45_profile_v1'));return p.photo.startsWith('data:image/jpeg')&&!!el('homeAvatar').querySelector('img')})()"))
    await pg.fill('#pfName','Евгений');await pg.fill('#pfW','95');await pg.fill('#pfBf','18');await pg.evaluate("document.querySelector('#pfGoal [data-v=\"lose\"]').click()")
    await pg.evaluate("el('pfSave').click()");await pg.wait_for_timeout(100)
    t=json.loads(await pg.evaluate("localStorage.getItem('gym45_nutrition_target_v1')"))
    ok('сохранение профиля пересчитывает норму питания',t['weight']==95 and t['bf']==18 and t['goal']=='lose',(t['weight'],t.get('bf'),t['goal']))
    ok('в профиле показана норма',await pg.evaluate("el('pfNorm').innerText.includes('ккал')&&el('pfNorm').innerText.includes('сухой массы')"))
    ok('профиль без горизонтальной прокрутки',await pg.evaluate("document.documentElement.scrollWidth<=innerWidth+1"))
    if SHOT:await pg.screenshot(path=SHOT+'/profile.png',full_page=True)
    await pg.evaluate("el('pfToFood').click()");await pg.wait_for_timeout(100)
    ok('в «Питании» форма показывает данные профиля',await pg.evaluate("[el('ntWeight').value,el('ntBf').value].join('|')")=='95|18')
    await pg.fill('#ntWeight','94');await pg.evaluate("el('ntCalc').click()");await pg.wait_for_timeout(100)
    ok('норма из «Питания» обновляет профиль',await pg.evaluate("JSON.parse(localStorage.getItem('gym45_profile_v1')).weight")==94)
    await pg.evaluate("show('gvt');g2Render()");await pg.wait_for_timeout(100)
    ok('новая программа GVT: масса тела подставлена из профиля',await pg.evaluate("el('g2Bw')&&el('g2Bw').value")=='94')
    await pg.reload();await pg.wait_for_timeout(300)
    ok('после перезапуска фото и имя на месте',await pg.evaluate("!!el('homeAvatar').querySelector('img')&&el('homeAvatar').getAttribute('aria-label')==='Профиль: Евгений'"))
    ok('ошибок JS нет',not errs,errs[:3])
    await b.close()
  print(f'\n{sum(R)}/{len(R)} PASS');sys.exit(0 if all(R) else 1)
asyncio.run(m())
